<?php
/**
 * Class: LoyaltyPointsManager
 * Description: Manages the calculation and application of loyalty points
 *              for registered customers using RFID card identification.
 * Author: [Your Name]
 * Date: 2024-03-10
 */
class LoyaltyPointsManager {
    private $conn;

    /**
     * Constructor for LoyaltyPointsManager class.
     *
     * @param mysqli $connection The database connection object.
     */
    public function __construct($connection) {
        $this->conn = $connection;
    }

    /**
     * Calculates the loyalty points earned based on the purchase amount.
     *
     * @param float $purchaseAmount The total purchase amount.
     * @return int The number of loyalty points earned.
     */
    public function calculatePoints($purchaseAmount) {
        // Validate that the purchase amount is a positive number
        if (!is_numeric($purchaseAmount) || $purchaseAmount < 0) {
            throw new InvalidArgumentException("Purchase amount must be a positive number.");
        }
        // Calculate points: 1 point per 20 pesos spent
        $points = floor($purchaseAmount / 20);
        // Return the calculated points
        return $points;
    }
}
